effect.script:
function rand01(n){ return (Math.abs(Math.sin(n) * 43758.5453) % 1.0); }
function hash1(x){ return rand01(x * 12.9898 + 78.233); }
function smoothNoise(t){
let i = Math.floor(t);
let f = t - i;
let a = hash1(i);
let b = hash1(i + 1.0);
let s = f*f*(3.0 - 2.0*f);
return a*(1.0 - s) + b*s;
}
function wrapReflect(v, limit){
if(limit <= 0) return v;
let L = Math.abs(limit);
let t = v + L;
t = t - Math.floor(t / (2.0*L)) * (2.0*L);
if(t > L) t = 2.0*L - t;
return t - L;
}
function wrapClamp(v, limit){
let L = Math.abs(limit);
return Math.max(-L, Math.min(L, v));
}
function axisShake(env, baseFreq, seed, randAmp, randFreq, waveAmp, waveFreq, phase){
let t = env.time * env.duration;
let fRand = randFreq <= 0 ? 0 : smoothNoise((t * randFreq * baseFreq) + seed*13.37) * 2.0 - 1.0;
let fWave = waveAmp === 0 ? 0 : Math.sin((t * waveFreq * baseFreq + phase) * Math.PI * 2.0);
return fRand * randAmp + fWave * waveAmp;
}
function computeOffsets(env,p){
let baseFreq = p.frequency;
let seed = p.seed;
let dx = axisShake(env, baseFreq, seed+1.0, p.xRandAmp, p.xRandFreq, p.xWaveAmp, p.xWaveFreq, p.xPhase);
let dy = axisShake(env, baseFreq, seed+2.0, p.yRandAmp, p.yRandFreq, p.yWaveAmp, p.yWaveFreq, p.yPhase);
let dz = axisShake(env, baseFreq, seed+3.0, p.zRandAmp, p.zRandFreq, p.zWaveAmp, p.zWaveFreq, p.zPhase);
let dTilt = axisShake(env, baseFreq, seed+4.0, p.tRandAmp, p.tRandFreq, p.tWaveAmp, p.tWaveFreq, p.tPhase);
dx *= p.amplitude; dy *= p.amplitude;
if(p.wrapX == 1){ dx = wrapReflect(dx, p.xRandAmp + p.xWaveAmp); } else if(p.wrapX == 2){ dx = wrapClamp(dx, p.xRandAmp + p.xWaveAmp); }
if(p.wrapY == 1){ dy = wrapReflect(dy, p.yRandAmp + p.yWaveAmp); } else if(p.wrapY == 2){ dy = wrapClamp(dy, p.yRandAmp + p.yWaveAmp); }
return {dx:dx, dy:dy, dz:dz, dTilt:dTilt};
}
function applyOffsets(el, off){
el.transform.location.x += off.dx;
el.transform.location.y += off.dy;
if(el.transform.scale){
el.transform.scale.x *= (1.0 + off.dz);
el.transform.scale.y *= (1.0 + off.dz);
}
el.transform.angle += off.dTilt;
return el;
}
function animate(env, el, p){
if(!p.motionBlur){
let off = computeOffsets(env,p);
return applyOffsets(el, off);
} else {
let n = 5;
let acc = {dx:0,dy:0,dz:0,dTilt:0};
let duration = p.mbLength * 0.05;
for(let i=0;i<n;i++){
let tPrev = env.time;
env.time = tPrev - (i/(n-1)) * duration;
let off = computeOffsets(env,p);
acc.dx += off.dx; acc.dy += off.dy; acc.dz += off.dz; acc.dTilt += off.dTilt;
env.time = tPrev;
}
acc.dx /= n; acc.dy /= n; acc.dz /= n; acc.dTilt /= n;
return applyOffsets(el, acc);
}
}

effect.shader:
float rand(vec2 co) {
return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}
void main() {
vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
vec2 st = acScreenNorm;
float t = seed + acTime * dissolveSpeed;
float r = rand(st * (1.0 + t * 0.1) + vec2(t * 1.33, t * 0.77));
float alpha = step(dissolvePercent, r);
gl_FragColor = texColor * alpha;
}
